  function auraFeaturePanel(){const blocks={noise:['auraNoiseTitle','auraNoiseBody','headphones'],comfort:['auraComfort','auraComfortBody','earbuds'],battery:['auraBatteryTitle','auraBatteryBody','phone']};const [title,body,id]=blocks[auraTab];return `<div class="aura-feature-copy"><span class="kicker">AURA / ${auraTab.toUpperCase()}</span><h3>${t(title)}</h3><p>${t(body)}</p><div class="aura-mini-specs"><span>Bluetooth 5.3</span><span>USB-C</span><span>Hi-Res Audio</span></div></div><div class="aura-feature-visual">${img(id)}</div>`}
  function auraFeatures(){return `<section class="section aura-features" id="aura-features"><div class="section-heading"><div>${tag('auraDetails')}<h2>${t('auraBuiltForYou')}</h2></div><p>${t('auraFeatureIntro')}</p></div>${has('tabs')?`<div class="aura-tabs tabs">${['noise','comfort','battery'].map(k=>button(t({noise:'auraNoise',comfort:'auraComfort',battery:'auraBattery'}[k]),`data-aura-tab="${k}"`,auraTab===k?'active':'')).join('')}</div><div class="aura-feature-panel" id="aura-feature-panel">${auraFeaturePanel()}</div>`:`<div class="aura-feature-cards">${[['headphones','auraDetails','auraNoiseBody'],['phone','auraConnected','auraDeviceIntro'],['earbuds','auraEveryday','auraBudsIntro']].map(([id,title,body],i)=>`<article><div class="aura-feature-image">${img(id)}<span>0${i+1}</span></div><h3>${t(title)}</h3><p>${t(body)}</p></article>`).join('')}</div>`}</section>`}
  function auraEditorial(){return `<section class="aura-editorial" id="story"><div class="aura-editorial-image"><img src="assets/images/showcase/aura-tech-editorial.png" alt="AURA / ${t('audio')}"></div><div><span class="kicker">DESIGNED AROUND YOU</span><h2>${t('auraConnected')}</h2><p>${t('auraStory')}</p><div class="aura-editorial-stats"><div><strong>01</strong><span>${t('auraEcosystem')}</span></div><div><strong>∞</strong><span>${t('auraPossibilities')}</span></div></div>${isShop()?button(t('showMore')+' ↗','data-action="continue-shopping"','primary'):'<a class="primary" href="#contact-section">'+t('contactUs')+' ↗</a>'}</div></section>`}
  function auraReviews(){return `<section class="section aura-review"><span class="kicker">${t('testimonials')}</span><div class="aura-review-rating">★★★★★</div><h2>${t('auraQuote'+(quote+1))}</h2><div class="aura-review-bottom"><div class="quote-person"><b>${['AK','MR','DL'][quote]}</b><div><strong>${['Alex K.','Maria R.','Daniel L.'][quote]}</strong><span>${t('demoReview')}</span></div></div><div class="quote-controls"><span>0${quote+1} / 03</span>${button('←','data-quote="-1" aria-label="'+t('previous')+'"')}${button('→','data-quote="1" aria-label="'+t('next')+'"')}</div></div></section>`}
