  function accountContent(){return accountTab==='profile'?`<form id="profile-form" class="account-form"><h3>${t('personal')}</h3><label>${t('fullname')}<input name="name" value="${esc(profile.name)}" required maxlength="80"></label><label>${t('email')}<input name="email" type="email" value="${esc(profile.email)}" required></label><label>${t('city')}<input name="city" value="${esc(profile.city)}" maxlength="80"></label><button class="primary">${t('save')}</button><p class="success-message" id="profile-status" role="status"></p></form>`:accountTab==='history'?`<div class="order-history"><h3>${t('history')}</h3><article><strong>${config.type==='game'?t('wins')+': '+wins:t('tasks')+': '+tasks.length}</strong><p>${config.type==='game'?t('draws')+': '+draws:t('done')+': '+tasks.filter(task=>task.done).length}</p></article></div>`:accountTab==='orders'?`<div class="order-history">${orders.map(o=>`<article><div><strong>${t('order')} #${o.id}</strong><span class="status-pill">${t(o.status)}</span></div><p>${o.date?new Date(o.date).toLocaleDateString(lang==='ro'?'ro-RO':lang==='en'?'en-GB':'ru-RU'):'06.11.2026'} · AURA / ${t('demo')}</p><b>${money(o.total)}</b></article>`).join('')}</div>`:`<div class="settings-panel"><h3>${t('notifications')}</h3><label class="filter-choice"><input type="checkbox" id="notify-check" ${profile.notify?'checked':''}>${t('notify')}</label><p>${t('formNote')}</p></div>`;}
  function accountDialog(){if(!authenticated){loginDialog();return;}if(isShop()){const top=route==='account'?scrollY:0;route='account';render();scrollTo({top,behavior:'instant'});return;}openDialog(`<div class="account-header"><span class="account-avatar">${esc(profile.name.split(' ').map(s=>s[0]).join('').slice(0,2))}</span><div>${tag('account')}<h2>${esc(profile.name)}</h2><p>${esc(profile.email)}</p></div></div><button type="button" class="account-logout" data-action="logout">${t('logout')} ↗</button><div class="tabs account-tabs">${['profile',isShop()?'orders':'history','settings'].map(k=>button(t(k),`data-account="${k}"`,accountTab===k?'active':'')).join('')}</div>${accountContent()}`,'account-dialog');}
