  function searchResults(){const q=search.toLocaleLowerCase();const entries=isShop()?products.map(p=>({title:t(p.name),attr:`data-product="${p.id}"`,type:t(p.category)})):isAura()?[...products.filter(p=>p.category==='audio').map(p=>({title:t(p.name),attr:`data-product="${p.id}"`,type:t('audio')})),...['aboutBrand','support'].map(k=>({title:t(k),attr:`data-search-nav="${k}"`,type:'AURA'}))]:['services','projects','team','contact'].map(k=>({title:t(k),attr:`data-search-nav="${k}"`,type:t(config.type)}));$('#search-results').innerHTML=entries.filter(e=>e.title.toLocaleLowerCase().includes(q)).map(e=>button(`<span>${esc(e.title)}<small>${esc(e.type)}</small></span>↗`,e.attr,'search-result')).join('')||`<p class="empty-state">${t('nothing')}</p>`}
  function setFilters(){const form=$('#product-filters');if(!form)return;const fd=new FormData(form);filter={...filter,category:fd.get('category'),materials:fd.getAll('material'),min:fd.get('min'),max:fd.get('max'),stock:fd.has('stock')};refreshCatalog()}
