  function winner(cells){for(const [a,b,c]of [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]])if(cells[a]&&cells[a]===cells[b]&&cells[a]===cells[c])return cells[a];return cells.every(Boolean)?'draw':null}
  function minimax(cells,player){const won=winner(cells);if(won)return {score:won==='O'?10:won==='X'?-10:0};let best={score:player==='O'?-Infinity:Infinity};for(let i=0;i<9;i++)if(!cells[i]){cells[i]=player;const value=minimax(cells,player==='O'?'X':'O').score;cells[i]='';if(player==='O'?value>best.score:value<best.score)best={score:value,index:i}}return best}
  function finish(){const won=winner(board);if(won){result=won==='X'?'win':won==='O'?'lose':'draw';if(won==='X')wins++;if(won==='draw')draws++;return true}return false}
  function refreshGame(){const top=scrollY;render();scrollTo(0,top)}
  function play(index){if(config.type!=='game'||board[index]||turn!=='X'||result)return;board[index]='X';if(finish()){refreshGame();return}turn='O';refreshGame();const current=round;botTimer=setTimeout(()=>{if(config.type!=='game'||current!==round)return;const empty=board.map((v,i)=>v?-1:i).filter(i=>i>=0);const index=difficulty==='hard'?minimax([...board],'O').index:empty[Math.floor(Math.random()*empty.length)];board[index]='O';finish();turn='X';refreshGame()},config.motion?420:0)}
  function resetGame(){clearTimeout(botTimer);round++;board=Array(9).fill('');turn='X';result='';refreshGame()}
